/**
 * Entrance animations: elements with `data-ae-anim` start invisible (see the CSS
 * generator) and get the `ae-in` class when they scroll into view, which plays their
 * keyframes once. Under prefers-reduced-motion the CSS shows them at once and this
 * does nothing.
 */
export function installEntranceAnimations(root: HTMLElement): () => void {
  if (typeof window === "undefined" || typeof IntersectionObserver !== "function") {
    for (const element of Array.from(root.querySelectorAll("[data-ae-anim]"))) element.classList.add("ae-in");
    return () => undefined;
  }
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
    for (const element of Array.from(root.querySelectorAll("[data-ae-anim]"))) element.classList.add("ae-in");
    return () => undefined;
  }
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          entry.target.classList.add("ae-in");
          observer.unobserve(entry.target);
        }
      }
    },
    { threshold: 0.15 },
  );
  const observe = () => {
    for (const element of Array.from(root.querySelectorAll("[data-ae-anim]:not(.ae-in)"))) observer.observe(element);
  };
  observe();
  // Elements added later (the editor pushing a draft) are picked up too.
  const mutations = typeof MutationObserver === "function" ? new MutationObserver(observe) : null;
  mutations?.observe(root, { childList: true, subtree: true });
  return () => {
    observer.disconnect();
    mutations?.disconnect();
  };
}

/**
 * Vertical parallax: elements with `data-ae-parallax` (-10 to 10) drift against the
 * scroll by up to that many percent of the distance from the middle of the screen. One
 * passive scroll listener, one transform per frame; nothing under reduced motion.
 */
export function installParallax(root: HTMLElement): () => void {
  if (typeof window === "undefined" || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return () => undefined;
  const elements = () => Array.from(root.querySelectorAll<HTMLElement>("[data-ae-parallax]"));
  if (elements().length === 0) return () => undefined;
  let frame = 0;
  const update = () => {
    frame = 0;
    const middle = window.innerHeight / 2;
    for (const element of elements()) {
      const speed = Number(element.dataset["aeParallax"]) || 0;
      // Measure without the current shift so the movement never feeds back on itself.
      const shift = Number(element.dataset["aeParallaxShift"] ?? 0);
      const box = element.getBoundingClientRect();
      const distance = box.top - shift + box.height / 2 - middle;
      const next = Math.round(distance * speed * -0.02 * 10) / 10;
      element.dataset["aeParallaxShift"] = String(next);
      element.style.translate = `0 ${next}px`;
    }
  };
  const schedule = () => {
    if (!frame) frame = requestAnimationFrame(update);
  };
  window.addEventListener("scroll", schedule, { passive: true });
  window.addEventListener("resize", schedule, { passive: true });
  schedule();
  return () => {
    if (frame) cancelAnimationFrame(frame);
    window.removeEventListener("scroll", schedule);
    window.removeEventListener("resize", schedule);
    for (const element of elements()) {
      element.style.translate = "";
      delete element.dataset["aeParallaxShift"];
    }
  };
}

files.posts.tsx:
/**
 * Blog rendering for the kit. `<ArmaturePost slug />` renders one post's layout in the
 * site's chrome; `<ArmaturePostList />` renders the list of published posts (from
 * content/posts/index.json) with optional filters. `useBuilderPosts()` returns the
 * published posts, so the site's router can plug them into a route ("/blog/<slug>").
 *
 * Filtering respects `publishedAt`: a post with no publishedAt is a draft; one whose
 * publishedAt is in the future is scheduled and not shown yet. The site is a static
 * React site — the scheduler cron function commits the post at the scheduled time.
 */
import { useMemo, useSyncExternalStore, type ReactElement } from "react";
import { ArmaturePage, useKitSnapshot } from "./renderer.tsx";
import type { PostDoc, PostIndexEntry } from "./types.ts";

/**
 * Rerender once a minute so a scheduled post's move to "published" doesn't need a page
 * reload. `subscribeMinute` implements a tiny store; `useSyncExternalStore` gives React a
 * pure `getSnapshot` (no Date.now() in render).
 */
const minuteListeners = new Set<() => void>();
let minuteTimer: ReturnType<typeof setInterval> | null = null;
function subscribeMinute(listener: () => void): () => void {
  minuteListeners.add(listener);
  if (!minuteTimer && typeof setInterval !== "undefined") {
    minuteTimer = setInterval(() => {
      for (const l of minuteListeners) l();
    }, 60_000);
  }
  return () => {
    minuteListeners.delete(listener);
    if (minuteListeners.size === 0 && minuteTimer) {
      clearInterval(minuteTimer);
      minuteTimer = null;
    }
  };
}
let cachedMinute = -1;
const getMinute = (): number => {
  const now = Date.now();
  const bucket = Math.floor(now / 60_000);
  if (bucket !== cachedMinute) cachedMinute = bucket;
  return cachedMinute;
};
const getServerMinute = () => 0;
function useNowMinute(): number {
  return useSyncExternalStore(subscribeMinute, getMinute, getServerMinute) * 60_000;
}

export type PostListOpts = {
  /** Cap the number of posts shown. */
  limit?: number;
  /** Only posts in this category slug. */
  category?: string;
  /** Only posts in this tag slug. */
  tag?: string;
};

/** Every published post (draft/scheduled posts filtered out), newest first. */
export function useBuilderPosts(opts: PostListOpts = {}): PostIndexEntry[] {
  const snapshot = useKitSnapshot();
  const nowMs = useNowMinute();
  return useMemo(() => filterPosts(snapshot.postIndex.posts, opts, () => nowMs), [snapshot.postIndex, opts, nowMs]);
}

export function filterPosts(all: PostIndexEntry[], opts: PostListOpts, now: () => number): PostIndexEntry[] {
  const stamp = now();
  const shown = all.filter((entry) => {
    if (!entry.publishedAt) return false;
    const at = Date.parse(entry.publishedAt);
    if (!Number.isFinite(at) || at > stamp) return false;
    if (opts.category && !entry.categories.includes(opts.category)) return false;
    if (opts.tag && !entry.tags.includes(opts.tag)) return false;
    return true;
  });
  if (opts.limit && opts.limit > 0) return shown.slice(0, opts.limit);
  return shown;
}

/** The list of posts, as an unordered list of cards. Style with `.ae-post-card` and children. */
export function ArmaturePostList(props: PostListOpts & { className?: string }): ReactElement {
  const entries = useBuilderPosts(props);
  if (entries.length === 0) return <p className={props.className}>No posts yet.</p>;
  return (
    <ul className={props.className ?? "ae-post-list"}>
      {entries.map((post) => (
        <li key={post.slug} className="ae-post-card">
          {post.coverImage && <a href={post.path} className="ae-post-card-image"><img src={post.coverImage} alt="" /></a>}
          <div className="ae-post-card-body">
            <h3 className="ae-post-card-title"><a href={post.path}>{post.title}</a></h3>
            <p className="ae-post-card-meta">
              {post.authorName && <span>{post.authorName}</span>}
              {post.publishedAt && <time dateTime={post.publishedAt}>{formatDate(post.publishedAt)}</time>}
            </p>
            {post.excerpt && <p className="ae-post-card-excerpt">{post.excerpt}</p>}
          </div>
        </li>
      ))}
    </ul>
  );
}

/** One post's layout, from its slug. Renders nothing while the post is a draft or scheduled. */
export function ArmaturePost({ slug }: { slug: string }): ReactElement | null {
  const snapshot = useKitSnapshot();
  const post: PostDoc | undefined = snapshot.posts[slug];
  const nowMs = useNowMinute();
  if (!post) return null;
  if (!post.settings.publishedAt || Date.parse(post.settings.publishedAt) > nowMs) return null;
  const layoutLike = { version: 1 as const, pageSlug: post.slug, path: post.path, label: post.settings.title, seo: post.settings.seo, root: post.root };
  return <ArmaturePage slug={post.slug} layout={layoutLike} />;
}

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString(undefined, { year: "numeric", month: "long", day: "numeric" });
  } catch {
    return iso.slice(0, 10);
  }
}

files.renderer.tsx:
/**
 * The renderer: <ArmaturePage> renders a layout, <ArmatureSlot> lets a coded page render
 * its layout (falling back to its registered site sections), <ArmatureRoute> serves
 * builder-only pages by their path. Semantic HTML only; no innerHTML anywhere. The
 * stylesheet for a page is generated from the tree and mounted as a <style> text node.
 */
import { createElement, useEffect, useMemo, useRef, useSyncExternalStore, type ComponentType, type ReactNode } from "react";
import { pageCss } from "./css.ts";
import { installEntranceAnimations, installParallax } from "./motion.ts";
import { safeAttributeName } from "./sanitize.ts";
import { computePageHead, type HeadTag } from "./seo.ts";
import type { KitSnapshot, KitStore } from "./store.ts";
import { chromeSlug, isChromeSlug, type ChromePart, type Element, type LayoutDoc, type SiteSectionProps } from "./types.ts";
import { cssIdent, googleFontsHref } from "./values.ts";
import { KIT_VERSION } from "./version.ts";
import { getWidget } from "./widgets.tsx";

export type KitRuntime = {
  store: KitStore;
  /** Slugs declared in content/schema.json: their layouts drive <ArmatureSlot>, never <ArmatureRoute>. */
  codedSlugs: Set<string>;
  /** Slots currently mounted on the page, with the section keys they would show without a layout. */
  slots: Map<string, string[]>;
  onSlotsChange: Set<() => void>;
  /** Where the Form widget sends entries (the dashboard's form-submit function), when the site set it. */
  forms?: { endpoint: string; siteId: string };
  /** Coded pages' live paths by slug (from content/schema.json), for the Nav Menu widget's page links. */
  pagePaths: Map<string, string>;
};

let runtime: KitRuntime | null = null;

export function setKitRuntime(next: KitRuntime): void {
  runtime = next;
}

export function getKitRuntime(): KitRuntime {
  if (!runtime) throw new Error("Armature: call createArmatureKit() before rendering <ArmaturePage>, <ArmatureSlot> or <ArmatureRoute>.");
  return runtime;
}

const noop = () => () => undefined;
const emptySnapshot: KitSnapshot = { content: {}, layouts: {}, kit: null as unknown as KitSnapshot["kit"], editMode: false, editing: null, editEpoch: {}, posts: {}, postIndex: { version: 1, posts: [] } };

export function useKitSnapshot(): KitSnapshot {
  const store = runtime?.store;
  return useSyncExternalStore(store ? store.subscribe : noop, store ? store.getSnapshot : () => emptySnapshot, store ? store.getSnapshot : () => emptySnapshot);
}

/** "/about/" and "/about" are the same page. */
export function normalizePath(path: string): string {
  let out = (path || "/").split(/[?#]/)[0] ?? "/";
  if (!out.startsWith("/")) out = `/${out}`;
  out = out.replace(/\/+$/, "").toLowerCase();
  return out === "" ? "/" : out;
}

// --- elements --------------------------------------------------------------------------------

/** Image elements in document order, so the first picture on a page loads eagerly. */
type RenderState = { imageOrder: Map<string, number>; page: string };

function imageOrderOf(root: Element[]): Map<string, number> {
  const order = new Map<string, number>();
  const walk = (elements: Element[]) => {
    for (const element of elements) {
      if (element.type === "image") order.set(element.id, order.size);
      if (element.children) walk(element.children);
    }
  };
  walk(root);
  return order;
}

/**
 * One element. While it is being typed into on the page the renderer hands React the very
 * same output as before, so React leaves the edited DOM alone; when the edit ends the
 * element remounts (a new key) from the saved value, discarding the browser's markup.
 */
function ElementView({ element, state }: { element: Element; state: RenderState }) {
  const snapshot = useKitSnapshot();
  return <ElementBody key={snapshot.editEpoch[element.id] ?? 0} element={element} state={state} />;
}

function ElementBody({ element, state }: { element: Element; state: RenderState }) {
  const snapshot = useKitSnapshot();
  const frozen = snapshot.editing === element.id;
  // While frozen the inputs read as null, so the memo keeps returning the output from the
  // moment the edit began (the same element object, which React skips).
  const liveElement = frozen ? null : element;
  const liveState = frozen ? null : state;
  const liveKit = frozen ? null : snapshot.kit;
  const liveMode = frozen ? null : snapshot.editMode;
  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally stale while the element is being edited
  return useMemo(() => renderElement(element, state, snapshot), [liveElement, liveState, liveKit, liveMode]);
}

function renderElement(element: Element, state: RenderState, snapshot: KitSnapshot): ReactNode {
  const render = getWidget(element.type);
  if (element.type === "site-section") return <SiteSectionView element={element} state={state} />;
  if (!render) {
    if (snapshot.editMode) {
      return (
        <div className={`ae-el ae-${cssIdent(element.id)} ae-unsupported`} data-ae-id={element.id} data-ae-type={element.type} style={{ padding: 12, border: "1px dashed #a32d2d", color: "#a32d2d", fontSize: 13 }}>
          Unsupported element: {element.type === "unsupported" ? String((element.props as { originalType?: string }).originalType ?? "unknown") : element.type}
        </div>
      );
    }
    warnOnce(element.type);
    return null;
  }
  const common: Record<string, string | undefined> & { className: string } = {
    className: `ae-el ae-${cssIdent(element.id)} ae-${cssIdent(element.type)}${element.advanced.cssClasses ? ` ${element.advanced.cssClasses.replace(/[<>"'&\\]/g, "")}` : ""}`,
    id: element.advanced.cssId ? cssIdent(element.advanced.cssId) : undefined,
    "data-ae-id": element.id,
    "data-ae-type": element.type,
    "data-ae-anim": element.advanced.animation && element.advanced.animation.type !== "none" ? element.advanced.animation.type : undefined,
    "data-ae-parallax": element.advanced.scroll?.parallax ? String(Math.max(-10, Math.min(10, element.advanced.scroll.parallax))) : undefined,
  };
  for (const attribute of element.advanced.attributes ?? []) {
    if (safeAttributeName(attribute.name)) common[attribute.name.toLowerCase()] = attribute.value;
  }
  const imageIndex = element.type === "image" ? (state.imageOrder.get(element.id) ?? -1) : -1;
  const children = element.children?.map((child) => <ElementView key={child.id} element={child} state={state} />);
  return <>{render({ element, common, children, kit: snapshot.kit, editMode: snapshot.editMode, imageIndex, page: state.page })}</>;
}


function SiteSectionView({ element }: { element: Element; state: RenderState }) {
  const snapshot = useKitSnapshot();
  const props = element.props as SiteSectionProps;
  const registration = getKitRuntime().store.getSection(props.key);
  const className = `ae-el ae-${cssIdent(element.id)} ae-site-section${element.advanced.cssClasses ? ` ${element.advanced.cssClasses.replace(/[<>"'&\\]/g, "")}` : ""}`;
  if (!registration) {
    if (!snapshot.editMode) return null;
    return (
      <div className={className} data-ae-id={element.id} data-ae-type="site-section" data-ae-section={props.key} style={{ padding: 16, border: "1px dashed #8a4b00", color: "#8a4b00", fontSize: 13 }}>
        The site has no section registered as "{props.key}".
      </div>
    );
  }
  const Component = registration.component as ComponentType;
  return (
    <div className={className} data-ae-id={element.id} data-ae-type="site-section" data-ae-section={props.key} id={element.advanced.cssId ? cssIdent(element.advanced.cssId) : undefined}>
      <Component />
    </div>
  );
}

const warned = new Set<string>();
function warnOnce(type: string): void {
  if (warned.has(type)) return;
  warned.add(type);
  if (typeof console !== "undefined") console.warn(`Armature: no widget renders "${type}"; the element was skipped. Update src/lib/armature-kit.`);
}

// --- pages ------------------------------------------------------------------------------------

/**
 * Every head tag the layout and site kit ask for, applied to `document.head` on the
 * client. SSR sites should use `computePageHead(layout, siteKit)` in their route.head()
 * (see kit/README.md) so Google receives the tags in the initial HTML.
 */
function usePageSeo(layout: LayoutDoc | undefined) {
  const snapshot = useKitSnapshot();
  useEffect(() => {
    if (!layout || typeof document === "undefined") return;
    const tags = computePageHead(layout, snapshot.kit, { pageLabel: layout.label });
    applyHeadTags(tags);
  }, [layout, snapshot.kit]);
}

/**
 * Insert the tags into document.head, replacing the ones we wrote last time so nothing
 * accumulates when the visitor navigates from page to page.
 */
export function applyHeadTags(tags: HeadTag[]): void {
  if (typeof document === "undefined") return;
  // Remove tags we owned last time (marked with data-armature-head).
  document.head.querySelectorAll("[data-armature-head]").forEach((node) => node.remove());
  for (const tag of tags) {
    if (tag.tag === "title") {
      // Title is a special case: replace textContent of the existing <title>, adding it if missing.
      let element = document.head.querySelector("title");
      if (!element) {
        element = document.createElement("title");
        element.setAttribute("data-armature-head", "");
        document.head.appendChild(element);
      }
      element.textContent = tag.content;
      continue;
    }
    if (tag.tag === "script") {
      const element = document.createElement("script");
      element.type = tag.type;
      element.setAttribute("data-armature-head", "");
      element.textContent = tag.content;
      document.head.appendChild(element);
      continue;
    }
    const element = document.createElement(tag.tag);
    for (const [key, value] of Object.entries(tag.attrs)) element.setAttribute(key, value);
    element.setAttribute("data-armature-head", "");
    document.head.appendChild(element);
  }
}

/**
 * React component for SPA sites: renders no visible output but keeps the head tags for
 * the given layout up to date. Place it near <ArmaturePage> or inside your page components
 * to have SEO fields applied on the client. SSR sites should prefer computePageHead()
 * inside route.head() so Google sees the tags in the initial HTML.
 */
export function ArmatureHead({ layout, pageUrl, pageLabel }: { layout: LayoutDoc; pageUrl?: string; pageLabel?: string }): null {
  const snapshot = useKitSnapshot();
  useEffect(() => {
    if (typeof document === "undefined") return;
    const tags = computePageHead(layout, snapshot.kit, { pageUrl, pageLabel: pageLabel ?? layout.label });
    applyHeadTags(tags);
  }, [layout, snapshot.kit, pageUrl, pageLabel]);
  return null;
}

/**
 * The kit's Google fonts as one <link> in the document head (created with the DOM API,
 * updated in place when the kit's font list changes, removed when it empties).
 */
function useKitFonts(kit: KitSnapshot["kit"]): void {
  const href = useMemo(() => googleFontsHref(kit), [kit]);
  useEffect(() => {
    if (typeof document === "undefined") return;
    let link = document.head.querySelector<HTMLLinkElement>("link[data-armature-fonts]");
    if (!href) {
      link?.remove();
      return;
    }
    if (!link) {
      link = document.createElement("link");
      link.rel = "stylesheet";
      link.setAttribute("data-armature-fonts", "");
      document.head.appendChild(link);
    }
    if (link.getAttribute("href") !== href) link.setAttribute("href", href);
  }, [href]);
}

/** Render one layout by slug (or a layout object) inside the kit's scope. */
export function ArmaturePage({ slug, layout: given }: { slug: string; layout?: LayoutDoc }) {
  const snapshot = useKitSnapshot();
  const layout = given ?? snapshot.layouts[slug];
  const builderPage = !getKitRuntime().codedSlugs.has(slug) && !isChromeSlug(slug);
  const css = useMemo(() => (layout ? pageCss(layout, snapshot.kit, { editMode: snapshot.editMode }) : ""), [layout, snapshot.kit, snapshot.editMode]);
  useKitFonts(snapshot.kit);
  const root = useRef<HTMLDivElement>(null);
  usePageSeo(layout);
  void builderPage;
  // Page settings the site's own frame responds to: <html data-armature-canvas="full"> for a
  // full-canvas page (hide the header and footer) and data-armature-hide-title. The kit
  // version is stamped on the root element so Armature can tell what is actually live on
  // the site (not just what is in the repo).
  const canvas = layout?.pageSettings?.fullCanvas ? "full" : null;
  const hideTitle = !!layout?.pageSettings?.hideTitle;
  useEffect(() => {
    if (typeof document === "undefined") return;
    const html = document.documentElement;
    if (canvas) html.setAttribute("data-armature-canvas", canvas);
    if (hideTitle) html.setAttribute("data-armature-hide-title", "");
    html.setAttribute("data-armature-kit", KIT_VERSION);
    return () => {
      html.removeAttribute("data-armature-canvas");
      html.removeAttribute("data-armature-hide-title");
    };
  }, [canvas, hideTitle]);
  useEffect(() => {
    if (!root.current) return;
    const stopEntrances = installEntranceAnimations(root.current);
    // Parallax moves elements while scrolling; the editor keeps them still so handles line up.
    const stopParallax = snapshot.editMode ? () => undefined : installParallax(root.current);
    return () => {
      stopEntrances();
      stopParallax();
    };
  }, [layout, snapshot.editMode]);
  const state = useMemo<RenderState>(() => ({ imageOrder: layout ? imageOrderOf(layout.root) : new Map(), page: slug }), [layout, slug]);
  if (!layout) return null;
  return (
    <div ref={root} className={`ae-root${layout.pageSettings?.fullCanvas ? " ae-full-canvas" : ""}`} data-ae-page={slug}>
      <style data-armature-page={slug}>{css}</style>
      {layout.root.map((element) => (
        <ElementView key={element.id} element={element} state={state} />
      ))}
    </div>
  );
}

/**
 * On a coded page: the page's layout when one exists, else the registered site sections
 * named in `defaults`, in order. The editor uses `defaults` to seed the page's tree.
 */
export function ArmatureSlot({ slug, defaults = [] }: { slug: string; defaults?: string[] }) {
  const snapshot = useKitSnapshot();
  const kit = getKitRuntime();
  const key = defaults.join(",");
  useEffect(() => {
    kit.slots.set(slug, key ? key.split(",") : []);
    for (const listener of kit.onSlotsChange) listener();
    return () => {
      kit.slots.delete(slug);
      for (const listener of kit.onSlotsChange) listener();
    };
  }, [kit, slug, key]);
  const layout = snapshot.layouts[slug];
  if (layout) return <ArmaturePage slug={slug} layout={layout} />;
  return (
    <>
      {defaults.map((sectionKey) => {
        const registration = kit.store.getSection(sectionKey);
        if (!registration) return null;
        return createElement(registration.component as ComponentType, { key: sectionKey });
      })}
    </>
  );
}

function subscribeLocation(listener: () => void) {
  window.addEventListener("popstate", listener);
  window.addEventListener("armature:navigated", listener);
  return () => {
    window.removeEventListener("popstate", listener);
    window.removeEventListener("armature:navigated", listener);
  };
}
const readPath = () => (typeof window === "undefined" ? "/" : window.location.pathname);

/**
 * The site's header or footer: the part built in the editor (content/layouts/_header.json
 * or _footer.json) when the site has one, else `fallback` (the coded header or footer).
 * Wrap nothing else around it: it renders the <header> or <footer> itself.
 */
export function ArmatureChrome({ part, fallback = null }: { part: ChromePart; fallback?: ReactNode }) {
  const snapshot = useKitSnapshot();
  const slug = chromeSlug(part);
  const layout = snapshot.layouts[slug];
  if (!layout) return <>{fallback}</>;
  const Tag = part === "header" ? "header" : "footer";
  return (
    <Tag className={`ae-chrome ae-chrome-${part}`} data-armature-chrome="" data-armature-part={part}>
      <ArmaturePage slug={slug} layout={layout} />
    </Tag>
  );
}

/** The path a menu item's page lives at: a coded page from the schema, or a built page's own path. */
export function pagePathOf(slug: string, layouts: Record<string, LayoutDoc>): string | null {
  const coded = getKitRuntime().pagePaths.get(slug);
  if (coded) return coded;
  const layout = layouts[slug];
  return layout && !isChromeSlug(slug) ? layout.path : null;
}

/** The builder-only page at the current path, or `fallback` (the site's 404). Place it before the site's catch-all. */
export function ArmatureRoute({ fallback = null, path }: { fallback?: ReactNode; path?: string }) {
  const snapshot = useKitSnapshot();
  const livePath = useSyncExternalStore(subscribeLocation, readPath, readPath);
  const wanted = normalizePath(path ?? livePath);
  const kit = getKitRuntime();
  const layout = Object.values(snapshot.layouts).find((candidate) => !kit.codedSlugs.has(candidate.pageSlug) && !isChromeSlug(candidate.pageSlug) && normalizePath(candidate.path) === wanted);
  if (!layout) return <>{fallback}</>;
  return (
    <>
      <style data-armature-body="">{`body { background: var(--ae-page-background, #ffffff); }`}</style>
      <ArmaturePage slug={layout.pageSlug} layout={layout} />
    </>
  );
}

/** Every builder-only page (slug, path, label), for a site's own navigation. */
export function useBuilderPages(): { slug: string; path: string; label: string }[] {
  const snapshot = useKitSnapshot();
  const kit = getKitRuntime();
  return useMemo(
    () =>
      Object.values(snapshot.layouts)
        .filter((layout) => !kit.codedSlugs.has(layout.pageSlug) && !isChromeSlug(layout.pageSlug))
        .map((layout) => ({ slug: layout.pageSlug, path: layout.path, label: layout.label ?? layout.pageSlug })),
    [snapshot.layouts, kit],
  );
}

files.responsive.ts:
/**
 * Per-device values. A responsive wrapper is `{ desktop, tablet?, mobile? }` and is
 * recognised by its `desktop` key (no other value object in the model uses that key).
 * Tablet inherits desktop and mobile inherits tablet, the way Elementor does it.
 */
import type { Device, MaybeResponsive, Responsive } from "./types.ts";

export const DEVICES: readonly Device[] = ["desktop", "tablet", "mobile"];

export function isResponsive<T>(value: MaybeResponsive<T> | undefined): value is Responsive<T> {
  return typeof value === "object" && value !== null && !Array.isArray(value) && "desktop" in (value as object);
}

/** The value in force on a device, following the inheritance chain. */
export function resolve<T>(value: MaybeResponsive<T> | undefined, device: Device): T | undefined {
  if (value === undefined) return undefined;
  if (!isResponsive<T>(value)) return value;
  if (device === "mobile" && value.mobile !== undefined) return value.mobile;
  if ((device === "mobile" || device === "tablet") && value.tablet !== undefined) return value.tablet;
  return value.desktop;
}

/** The value set at exactly this device, with no inheritance (undefined when it inherits). */
export function own<T>(value: MaybeResponsive<T> | undefined, device: Device): T | undefined {
  if (value === undefined) return undefined;
  if (!isResponsive<T>(value)) return device === "desktop" ? value : undefined;
  return value[device];
}

export const hasOverride = <T>(value: MaybeResponsive<T> | undefined, device: Device): boolean =>
  device !== "desktop" && isResponsive<T>(value) && value[device] !== undefined;

/**
 * Set the value for one device and return the new (immutable) value. Setting the desktop
 * value on a plain value keeps it plain; clearing every override collapses the wrapper.
 * `next === undefined` clears that device.
 */
export function setAt<T>(value: MaybeResponsive<T> | undefined, device: Device, next: T | undefined): MaybeResponsive<T> | undefined {
  const current: Responsive<T> | undefined = value === undefined ? undefined : isResponsive<T>(value) ? { ...value } : { desktop: value };
  if (device === "desktop") {
    if (next === undefined) {
      if (!current || (current.tablet === undefined && current.mobile === undefined)) return undefined;
      // Keep the overrides; the desktop value falls back to the tablet one.
      return { ...current, desktop: (current.tablet ?? current.mobile) as T };
    }
    if (!current || (current.tablet === undefined && current.mobile === undefined)) return next;
    return { ...current, desktop: next };
  }
  if (next === undefined) {
    if (!current) return undefined;
    const out: Responsive<T> = { ...current };
    delete out[device];
    return out.tablet === undefined && out.mobile === undefined ? out.desktop : out;
  }
  const base: Responsive<T> = current ?? { desktop: next };
  return { ...base, [device]: next };
}

/** Every device with its resolved value, for generating one rule per breakpoint. */
export function perDevice<T>(value: MaybeResponsive<T> | undefined): { device: Device; value: T }[] {
  const out: { device: Device; value: T }[] = [];
  for (const device of DEVICES) {
    const v = own(value, device);
    if (v !== undefined) out.push({ device, value: v });
  }
  return out;
}

files.richText.tsx:
/**
 * The rich-text renderer: TipTap-compatible JSON in, React elements out. A small
 * whitelist (paragraph, headings, bold, italic, underline, strike, code, link, bullet
 * and ordered lists, blockquote, hard break, text colour and highlight, alignment).
 * Unknown nodes render their text; unknown marks are dropped; links are validated.
 * Never touches innerHTML.
 */
import { Fragment, createElement, type ReactNode } from "react";
import { newTabRel, safeHref } from "./sanitize.ts";
import type { RichBlock, RichDoc, RichInline, RichMark, TextAlign } from "./types.ts";
import { isColorValue, refToCss } from "./values.ts";

const styleForAlign = (align: TextAlign | undefined) => (align && align !== "left" ? { textAlign: align } : undefined);

function applyMarks(text: ReactNode, marks: RichMark[] | undefined, key: number): ReactNode {
  let out: ReactNode = text;
  for (const mark of marks ?? []) {
    switch (mark.type) {
      case "bold":
        out = <strong key={key}>{out}</strong>;
        break;
      case "italic":
        out = <em key={key}>{out}</em>;
        break;
      case "underline":
        out = <u key={key}>{out}</u>;
        break;
      case "strike":
        out = <s key={key}>{out}</s>;
        break;
      case "code":
        out = <code key={key}>{out}</code>;
        break;
      case "link": {
        const href = safeHref(mark.attrs?.href);
        if (!href) break;
        const blank = mark.attrs?.target === "_blank";
        out = (
          <a key={key} href={href} target={blank ? "_blank" : undefined} rel={blank ? newTabRel : undefined}>
            {out}
          </a>
        );
        break;
      }
      case "textStyle": {
        const color = mark.attrs?.color;
        if (color && isColorValue(color)) out = <span key={key} style={{ color: refToCss(color) }}>{out}</span>;
        break;
      }
      case "highlight": {
        const color = mark.attrs?.color;
        out = <mark key={key} style={color && isColorValue(color) ? { backgroundColor: refToCss(color) } : undefined}>{out}</mark>;
        break;
      }
      default:
        break;
    }
  }
  return out;
}

function renderInline(nodes: RichInline[] | undefined): ReactNode[] {
  return (nodes ?? []).map((node, index) => {
    if (node.type === "hardBreak") return <br key={index} />;
    if (node.type === "text") return <Fragment key={index}>{applyMarks(node.text, node.marks, index)}</Fragment>;
    return null;
  });
}

function renderBlock(block: RichBlock, key: number): ReactNode {
  switch (block.type) {
    case "paragraph":
      return (
        <p key={key} style={styleForAlign(block.attrs?.textAlign)}>
          {renderInline(block.content)}
        </p>
      );
    case "heading": {
      const level = Math.min(6, Math.max(1, Number(block.attrs?.level) || 2));
      return createElement(`h${level}`, { key, style: styleForAlign(block.attrs?.textAlign) }, ...renderInline(block.content));
    }
    case "bulletList":
      return <ul key={key}>{(block.content ?? []).map((item, index) => <li key={index}>{(item.content ?? []).map(renderBlock)}</li>)}</ul>;
    case "orderedList":
      return (
        <ol key={key} start={block.attrs?.start}>
          {(block.content ?? []).map((item, index) => (
            <li key={index}>{(item.content ?? []).map(renderBlock)}</li>
          ))}
        </ol>
      );
    case "blockquote":
      return <blockquote key={key}>{(block.content ?? []).map(renderBlock)}</blockquote>;
    default: {
      // An unknown block: keep its text so nothing silently disappears.
      const unknown = block as { content?: unknown };
      const text = Array.isArray(unknown.content) ? richTextToPlain({ type: "doc", content: unknown.content as RichBlock[] }) : "";
      return text ? <p key={key}>{text}</p> : null;
    }
  }
}

export function RichText({ doc }: { doc: RichDoc | undefined }) {
  if (!doc || !Array.isArray(doc.content)) return null;
  return <>{doc.content.map(renderBlock)}</>;
}

/** The plain text of a document, paragraphs joined by newlines. */
export function richTextToPlain(doc: RichDoc | undefined): string {
  if (!doc || !Array.isArray(doc.content)) return "";
  const inline = (nodes: RichInline[] | undefined): string => (nodes ?? []).map((node) => (node.type === "text" ? node.text : node.type === "hardBreak" ? "\n" : "")).join("");
  const block = (node: RichBlock): string => {
    switch (node.type) {
      case "paragraph":
      case "heading":
        return inline(node.content);
      case "bulletList":
      case "orderedList":
        return (node.content ?? []).map((item) => (item.content ?? []).map(block).join("\n")).join("\n");
      case "blockquote":
        return (node.content ?? []).map(block).join("\n");
      default:
        return "";
    }
  };
  return doc.content.map(block).join("\n");
}

/** A document holding one paragraph of plain text. */
export const plainDoc = (text: string): RichDoc => ({
  type: "doc",
  content: text.split(/\n{2,}/).map((paragraph) => ({ type: "paragraph", content: paragraph ? [{ type: "text", text: paragraph }] : [] })),
});

files.richTextDom.ts:
/**
 * Edit mode only: turn the DOM of a contenteditable rich-text element back into the
 * whitelisted TipTap-compatible JSON. Anything outside the whitelist is reduced to its
 * text; links keep only safe destinations; colours must look like colours.
 */
import type { RichBlock, RichDoc, RichInline, RichMark, TextAlign } from "./types.ts";
import { isColorValue } from "./values.ts";

const ALIGN: Record<string, TextAlign> = { left: "left", center: "center", right: "right", justify: "justify" };

const alignOf = (element: Element): TextAlign | undefined => {
  const style = (element as HTMLElement).style?.textAlign || element.getAttribute("align") || "";
  const align = ALIGN[style.toLowerCase()];
  return align && align !== "left" ? align : undefined;
};

function safeHref(value: string | null): string | null {
  if (!value) return null;
  const trimmed = value.trim();
  if (trimmed.startsWith("//")) return null;
  if (trimmed.startsWith("/") || trimmed.startsWith("#")) return trimmed;
  return /^(https?:\/\/|mailto:|tel:)/i.test(trimmed) ? trimmed : null;
}

function rgbToHex(value: string): string | null {
  const match = /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+))?\s*\)$/i.exec(value.trim());
  if (!match) return isColorValue(value) ? value : null;
  const hex = (part: string) => Number(part).toString(16).padStart(2, "0");
  const alpha = match[4] !== undefined ? Math.round(Number(match[4]) * 255) : 255;
  return `#${hex(match[1] ?? "0")}${hex(match[2] ?? "0")}${hex(match[3] ?? "0")}${alpha === 255 ? "" : hex(String(alpha))}`;
}

function marksFor(element: Element, inherited: RichMark[]): RichMark[] {
  const marks = [...inherited];
  const add = (mark: RichMark) => {
    if (!marks.some((existing) => existing.type === mark.type)) marks.push(mark);
  };
  const tag = element.tagName;
  const style = (element as HTMLElement).style;
  if (tag === "STRONG" || tag === "B" || (style && (style.fontWeight === "bold" || Number(style.fontWeight) >= 600))) add({ type: "bold" });
  if (tag === "EM" || tag === "I" || style?.fontStyle === "italic") add({ type: "italic" });
  if (tag === "U" || style?.textDecoration?.includes("underline") || style?.textDecorationLine?.includes("underline")) add({ type: "underline" });
  if (tag === "S" || tag === "STRIKE" || tag === "DEL" || style?.textDecoration?.includes("line-through") || style?.textDecorationLine?.includes("line-through")) add({ type: "strike" });
  if (tag === "CODE") add({ type: "code" });
  if (tag === "A") {
    const href = safeHref(element.getAttribute("href"));
    if (href) add({ type: "link", attrs: { href, target: element.getAttribute("target") === "_blank" ? "_blank" : null } });
  }
  if (tag === "MARK") {
    const color = style?.backgroundColor ? rgbToHex(style.backgroundColor) : null;
    add({ type: "highlight", attrs: color ? { color } : {} });
  }
  // A site colour keeps its kit reference (the editor's panel writes it as data-ae-color).
  const kitColor = element.getAttribute("data-ae-color");
  if (kitColor && kitColor.startsWith("kit:") && isColorValue(kitColor)) {
    add(tag === "MARK" ? { type: "highlight", attrs: { color: kitColor } } : { type: "textStyle", attrs: { color: kitColor } });
  }
  const color = tag === "FONT" ? element.getAttribute("color") : style?.color || null;
  if (color) {
    const hex = rgbToHex(color);
    if (hex) add({ type: "textStyle", attrs: { color: hex } });
  }
  return marks;
}

function inlineOf(node: Node, marks: RichMark[], out: RichInline[]): void {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = (node.textContent ?? "").replace(/\u00a0/g, " ");
    if (text === "") return;
    out.push(marks.length ? { type: "text", text, marks } : { type: "text", text });
    return;
  }
  if (node.nodeType !== Node.ELEMENT_NODE) return;
  const element = node as Element;
  if (element.tagName === "BR") {
    out.push({ type: "hardBreak" });
    return;
  }
  if (element.tagName === "SCRIPT" || element.tagName === "STYLE" || element.tagName === "TEMPLATE") return;
  const next = marksFor(element, marks);
  for (const child of Array.from(element.childNodes)) inlineOf(child, next, out);
}

const isBlockTag = (tag: string) => /^(P|H[1-6]|UL|OL|LI|BLOCKQUOTE|DIV|SECTION|ARTICLE|PRE|TABLE|TR|TD|TH)$/.test(tag);

function blocksOf(container: Node, out: RichBlock[]): void {
  let pending: RichInline[] = [];
  let pendingAlign: TextAlign | undefined;
  const flush = () => {
    if (pending.length > 0) {
      const paragraph: RichBlock = { type: "paragraph", content: pending };
      if (pendingAlign) paragraph.attrs = { textAlign: pendingAlign };
      out.push(paragraph);
    }
    pending = [];
    pendingAlign = undefined;
  };
  for (const child of Array.from(container.childNodes)) {
    if (child.nodeType === Node.ELEMENT_NODE && isBlockTag((child as Element).tagName)) {
      flush();
      const element = child as Element;
      const tag = element.tagName;
      if (/^H[1-6]$/.test(tag)) {
        const inline: RichInline[] = [];
        for (const grandchild of Array.from(element.childNodes)) inlineOf(grandchild, [], inline);
        const attrs: { level: 1 | 2 | 3 | 4 | 5 | 6; textAlign?: TextAlign } = { level: Number(tag[1]) as 1 | 2 | 3 | 4 | 5 | 6 };
        const align = alignOf(element);
        if (align) attrs.textAlign = align;
        out.push({ type: "heading", attrs, content: inline });
      } else if (tag === "UL" || tag === "OL") {
        const items = Array.from(element.children)
          .filter((item) => item.tagName === "LI")
          .map((item) => {
            const content: RichBlock[] = [];
            blocksOf(item, content);
            return { type: "listItem" as const, content: content.length ? content : [{ type: "paragraph" as const, content: [] }] };
          });
        const start = Number.parseInt(element.getAttribute("start") ?? "", 10);
        if (items.length) out.push(tag === "UL" ? { type: "bulletList", content: items } : Number.isFinite(start) && start >= 0 ? { type: "orderedList", attrs: { start }, content: items } : { type: "orderedList", content: items });
      } else if (tag === "BLOCKQUOTE") {
        const content: RichBlock[] = [];
        blocksOf(element, content);
        out.push({ type: "blockquote", content });
      } else if (tag === "P" || tag === "DIV" || tag === "LI") {
        // A paragraph, or a wrapper the browser made; nested blocks inside it are lifted.
        const hasBlocks = Array.from(element.children).some((grandchild) => isBlockTag(grandchild.tagName));
        if (hasBlocks) {
          blocksOf(element, out);
        } else {
          const inline: RichInline[] = [];
          for (const grandchild of Array.from(element.childNodes)) inlineOf(grandchild, [], inline);
          const paragraph: RichBlock = { type: "paragraph", content: inline };
          const align = alignOf(element);
          if (align) paragraph.attrs = { textAlign: align };
          out.push(paragraph);
        }
      } else {
        const inline: RichInline[] = [];
        for (const grandchild of Array.from(element.childNodes)) inlineOf(grandchild, [], inline);
        if (inline.length) out.push({ type: "paragraph", content: inline });
      }
      continue;
    }
    inlineOf(child, [], pending);
  }
  flush();
}

/** The whitelisted document for a contenteditable host. */
export function serializeRichText(host: Element): RichDoc {
  const content: RichBlock[] = [];
  blocksOf(host, content);
  return { type: "doc", content: content.length ? content : [{ type: "paragraph", content: [] }] };
}

files.rss.ts:
/**
 * RSS feed generation. Every post publish rewrites public/rss.xml alongside the post
 * file and the regenerated posts index, so /rss.xml stays in step with what the site
 * shows.
 */
import { absoluteUrl } from "./seo.ts";
import type { PostIndexEntry, SiteKit } from "./types.ts";

const escapeXml = (value: string): string => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
const rfc822 = (iso: string): string => {
  const date = new Date(iso);
  return Number.isFinite(date.getTime()) ? date.toUTCString() : new Date().toUTCString();
};

export type RssOptions = {
  /** Path on the site to serve the feed from (default /rss.xml). */
  feedPath?: string;
  /** Optional custom description; falls back to the site kit's default description. */
  description?: string;
};

/** The RSS 2.0 xml body for the site's published posts. */
export function rssXml(siteKit: SiteKit | null | undefined, posts: PostIndexEntry[], opts: RssOptions = {}): string {
  const seo = siteKit?.seo ?? {};
  const siteUrl = seo.siteUrl ?? "";
  const siteName = seo.siteName ?? "Website";
  const description = opts.description ?? seo.defaultDescription ?? `Posts from ${siteName}`;
  const feedUrl = absoluteUrl(siteUrl, opts.feedPath ?? "/rss.xml");
  const lines: string[] = ['<?xml version="1.0" encoding="UTF-8"?>', '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">', "  <channel>"];
  lines.push(`    <title>${escapeXml(siteName)}</title>`);
  if (siteUrl) lines.push(`    <link>${escapeXml(siteUrl)}</link>`);
  lines.push(`    <description>${escapeXml(description)}</description>`);
  if (feedUrl) lines.push(`    <atom:link href="${escapeXml(feedUrl)}" rel="self" type="application/rss+xml" />`);
  lines.push(`    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>`);
  const published = posts.filter((post) => post.publishedAt && Date.parse(post.publishedAt) <= Date.now()).slice(0, 50);
  for (const post of published) {
    const postUrl = absoluteUrl(siteUrl, post.path);
    lines.push("    <item>");
    lines.push(`      <title>${escapeXml(post.title)}</title>`);
    lines.push(`      <link>${escapeXml(postUrl)}</link>`);
    lines.push(`      <guid isPermaLink="true">${escapeXml(postUrl)}</guid>`);
    if (post.publishedAt) lines.push(`      <pubDate>${rfc822(post.publishedAt)}</pubDate>`);
    if (post.authorName) lines.push(`      <dc:creator>${escapeXml(post.authorName)}</dc:creator>`);
    if (post.excerpt) lines.push(`      <description>${escapeXml(post.excerpt)}</description>`);
    for (const category of post.categories ?? []) lines.push(`      <category>${escapeXml(category)}</category>`);
    lines.push("    </item>");
  }
  lines.push("  </channel>", "</rss>");
  return lines.join("\n") + "\n";
}

files.sanitize.ts:
/**
 * Sanitizers used by the renderer and the CSS generator. Everything that reaches the
 * page from a layout file passes through one of these. No dependencies.
 */

/** Links may only use https, http, mailto, tel, a site path (/...) or a fragment (#...). */
export function safeHref(value: string | undefined | null): string | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (trimmed === "" || trimmed.startsWith("//")) return undefined;
  if (trimmed.startsWith("/") || trimmed.startsWith("#")) return trimmed;
  return /^(https?:\/\/|mailto:|tel:)/i.test(trimmed) ? trimmed : undefined;
}

/** Media may come from the site itself, from https, or be an inline image preview in the editor. */
export function safeMediaSrc(value: string | undefined | null): string | undefined {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (trimmed.startsWith("/") && !trimmed.startsWith("//") && !trimmed.includes("..")) return trimmed;
  if (/^https:\/\//i.test(trimmed)) return trimmed;
  if (/^data:image\/(png|jpeg|webp|gif);base64,/i.test(trimmed)) return trimmed;
  return undefined;
}

/** A `rel` for a link that opens a new tab. */
export const newTabRel = "noopener noreferrer";

const CSS_MAX = 20_000;

/**
 * Custom CSS for one element: no @import, no javascript:, no expression(), no
 * behavior:, no url() to another origin, no closing tags. Returns "" when nothing
 * safe is left.
 */
export function sanitizeCss(input: string): string {
  let css = input.slice(0, CSS_MAX);
  css = css.replace(/<\/?\s*style[^>]*>/gi, "");
  css = css.replace(/@import[^;]*;?/gi, "");
  css = css.replace(/@charset[^;]*;?/gi, "");
  css = css.replace(/expression\s*\(/gi, "-blocked(");
  css = css.replace(/behavior\s*:/gi, "-blocked:");
  css = css.replace(/-moz-binding\s*:/gi, "-blocked:");
  css = css.replace(/javascript\s*:/gi, "blocked:");
  css = css.replace(/url\(\s*(['"]?)([^'")]*)\1\s*\)/gi, (_match, _quote: string, target: string) => {
    const trimmed = target.trim();
    const ok = (trimmed.startsWith("/") && !trimmed.startsWith("//")) || /^https:\/\//i.test(trimmed) || /^data:image\/(png|jpeg|webp|gif);base64,/i.test(trimmed);
    return ok ? `url("${trimmed.replace(/"/g, "")}")` : "none";
  });
  return css.trim();
}

/** HTML attribute names an element may carry from `advanced.attributes`. */
export function safeAttributeName(name: string): boolean {
  if (!/^[a-z][a-z0-9-]{0,40}$/i.test(name)) return false;
  const lowered = name.toLowerCase();
  if (lowered.startsWith("on")) return false;
  return !["href", "src", "style", "srcdoc", "action", "formaction", "class", "id", "xlink:href"].includes(lowered);
}

files.seo.ts:
/**
 * SEO helpers: turn a page's layout (with its seo block), the site kit's siteSeo and
 * the page's absolute URL into the exact head tags Google should see. Also generates
 * sitemap.xml and robots.txt for the publish function.
 *
 * The kit runs the SPA fallback (an `<ArmatureHead>` React component in ./renderer.tsx)
 * that inserts these tags into `document.head` via useEffect. For SSR sites (TanStack
 * Start, Next, Remix) use `computePageHead(layout, siteKit, opts)` inside route.head()
 * and return the array to the framework — see kit/README.md.
 *
 * Pure TypeScript. No dependencies, no DOM.
 */
import type { Element, LayoutDoc, LocalBusinessData, PageStructuredData, SiteKit } from "./types.ts";

export type HeadTag =
  | { tag: "title"; content: string }
  | { tag: "meta"; attrs: Record<string, string> }
  | { tag: "link"; attrs: Record<string, string> }
  | { tag: "script"; type: "application/ld+json"; content: string };

export type PageHeadOpts = {
  /** The page's absolute URL, e.g. https://acmehomes.com/about/. Leaving it out uses the layout's own path unresolved. */
  pageUrl?: string;
  /** A page label to fall back on for the title when seo.title is empty (usually schema.json's label or layout.label). */
  pageLabel?: string;
};

const trim = (value?: string): string => (typeof value === "string" ? value.trim() : "");
const escapeHtml = (value: string): string => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const escapeXml = (value: string): string => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
const isAbs = (value: string): boolean => /^https?:\/\//i.test(value);

/** Turn a possibly-relative address into an absolute URL against the site URL. */
export function absoluteUrl(siteUrl: string | undefined, address: string): string {
  if (!address) return "";
  if (isAbs(address)) return address;
  const base = trim(siteUrl);
  if (!base) return address;
  const clean = base.replace(/\/$/, "");
  if (address.startsWith("/")) return `${clean}${address}`;
  return `${clean}/${address}`;
}

/** Apply the site's title pattern ("%page% | %site%") to a page title. */
export function applyTitlePattern(pattern: string | undefined, page: string, site: string): string {
  const clean = trim(pattern) || "%page%";
  return clean.replace(/%page%/g, page).replace(/%site%/g, site).replace(/\s+\|\s*$/, "").trim() || page;
}

// --- structured data --------------------------------------------------------------------

/** Turn business data into the LocalBusiness / Organization JSON-LD object. */
function businessLd(kind: "LocalBusiness" | "Organization", data: LocalBusinessData | undefined, siteUrl: string, siteName: string): Record<string, unknown> | null {
  const merged = data ?? {};
  const name = trim(merged.name) || siteName;
  if (!name) return null;
  const ld: Record<string, unknown> = { "@context": "https://schema.org", "@type": trim(merged.type) || kind, name };
  if (siteUrl) ld["url"] = siteUrl;
  if (merged.telephone) ld["telephone"] = merged.telephone;
  if (merged.email) ld["email"] = `mailto:${merged.email.replace(/^mailto:/i, "")}`;
  if (merged.logo) ld["logo"] = absoluteUrl(siteUrl, merged.logo);
  const address: Record<string, string> = { "@type": "PostalAddress" };
  if (merged.streetAddress) address["streetAddress"] = merged.streetAddress;
  if (merged.addressLocality) address["addressLocality"] = merged.addressLocality;
  if (merged.addressRegion) address["addressRegion"] = merged.addressRegion;
  if (merged.postalCode) address["postalCode"] = merged.postalCode;
  if (merged.addressCountry) address["addressCountry"] = merged.addressCountry;
  if (Object.keys(address).length > 1) ld["address"] = address;
  if (typeof merged.latitude === "number" && typeof merged.longitude === "number") ld["geo"] = { "@type": "GeoCoordinates", latitude: merged.latitude, longitude: merged.longitude };
  if (merged.openingHours) ld["openingHours"] = merged.openingHours;
  if (merged.priceRange && kind === "LocalBusiness") ld["priceRange"] = merged.priceRange;
  if (merged.sameAs && merged.sameAs.length) ld["sameAs"] = merged.sameAs;
  return ld;
}

/** Walk the layout to find an accordion by id and return its items as FAQPage entities. */
function findAccordion(root: Element[], id: string): Element | null {
  for (const el of root) {
    if (el.id === id && el.type === "accordion") return el;
    if (el.children) {
      const found = findAccordion(el.children, id);
      if (found) return found;
    }
  }
  return null;
}

/** Turn an accordion element's items into an FAQPage JSON-LD object. */
function faqLd(accordion: Element): Record<string, unknown> | null {
  const items = ((accordion.props as { items?: unknown }).items ?? []) as { title?: string; content?: string }[];
  if (!Array.isArray(items) || items.length === 0) return null;
  const clean = items
    .filter((item) => item && typeof item.title === "string" && typeof item.content === "string" && item.title.trim() && item.content.trim())
    .map((item) => ({ "@type": "Question", name: (item.title ?? "").trim(), acceptedAnswer: { "@type": "Answer", text: (item.content ?? "").trim() } }));
  if (clean.length === 0) return null;
  return { "@context": "https://schema.org", "@type": "FAQPage", mainEntity: clean };
}

/** Turn the structured data setting and site data into a JSON-LD object, or null. */
export function structuredDataLd(
  data: PageStructuredData | undefined,
  layout: LayoutDoc,
  siteKit: SiteKit | null | undefined,
  pageUrl: string,
): Record<string, unknown> | null {
  if (!data || data.kind === "none") return null;
  const siteSeo = siteKit?.seo ?? {};
  const siteName = trim(siteSeo.siteName);
  const siteUrl = trim(siteSeo.siteUrl);
  if (data.kind === "LocalBusiness" || data.kind === "Organization") {
    const combined: LocalBusinessData = { ...(siteSeo.business ?? {}), ...(data.override ?? {}) };
    return businessLd(data.kind, combined, siteUrl, siteName);
  }
  if (data.kind === "Article") {
    const a = data.article;
    const ld: Record<string, unknown> = { "@context": "https://schema.org", "@type": "Article" };
    if (a.headline) ld["headline"] = a.headline;
    if (a.description) ld["description"] = a.description;
    if (a.image) ld["image"] = absoluteUrl(siteUrl, a.image);
    if (a.author) ld["author"] = { "@type": "Person", name: a.author };
    if (a.datePublished) ld["datePublished"] = a.datePublished;
    if (a.dateModified) ld["dateModified"] = a.dateModified;
    if (pageUrl) ld["mainEntityOfPage"] = pageUrl;
    return ld;
  }
  if (data.kind === "FAQ") {
    if (!data.fromAccordionId) return null;
    const accordion = findAccordion(layout.root, data.fromAccordionId);
    if (!accordion) return null;
    return faqLd(accordion);
  }
  if (data.kind === "BreadcrumbList") {
    const items = data.items
      .filter((item) => item && item.name && item.url)
      .map((item, index) => ({ "@type": "ListItem", position: index + 1, name: item.name, item: absoluteUrl(siteUrl, item.url) }));
    if (items.length === 0) return null;
    return { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: items };
  }
  return null;
}

// --- head tags --------------------------------------------------------------------------

/** Every head tag Google should see for a page, given its layout and the site kit's seo block. */
export function computePageHead(layout: LayoutDoc, siteKit: SiteKit | null | undefined, opts: PageHeadOpts = {}): HeadTag[] {
  const seo = layout.seo ?? {};
  const siteSeo = siteKit?.seo ?? {};
  const siteName = trim(siteSeo.siteName);
  const pageLabel = trim(seo.title) || trim(opts.pageLabel) || trim(layout.label) || layout.pageSlug;
  const title = applyTitlePattern(siteSeo.titlePattern, pageLabel, siteName);
  const description = trim(seo.description) || trim(siteSeo.defaultDescription);
  const pageUrl = trim(opts.pageUrl) || (siteSeo.siteUrl ? absoluteUrl(siteSeo.siteUrl, layout.path || "/") : "");
  const canonical = trim(seo.canonical) || pageUrl;
  const shareImageRaw = trim(seo.ogImage) || trim(siteSeo.defaultShareImage);
  const shareImage = shareImageRaw ? absoluteUrl(siteSeo.siteUrl, shareImageRaw) : "";
  const ogTitle = trim(seo.ogTitle) || title;
  const ogDescription = trim(seo.ogDescription) || description;
  const twitterTitle = trim(seo.twitterTitle) || ogTitle;
  const twitterDescription = trim(seo.twitterDescription) || ogDescription;
  const twitterImageRaw = trim(seo.twitterImage) || shareImageRaw;
  const twitterImage = twitterImageRaw ? absoluteUrl(siteSeo.siteUrl, twitterImageRaw) : "";

  const tags: HeadTag[] = [{ tag: "title", content: title }];
  if (description) tags.push({ tag: "meta", attrs: { name: "description", content: description } });
  const robots: string[] = [];
  if (seo.noindex) robots.push("noindex");
  if (seo.nofollow) robots.push("nofollow");
  if (robots.length) tags.push({ tag: "meta", attrs: { name: "robots", content: robots.join(", ") } });
  if (canonical) tags.push({ tag: "link", attrs: { rel: "canonical", href: canonical } });
  // Open Graph
  tags.push({ tag: "meta", attrs: { property: "og:type", content: "website" } });
  tags.push({ tag: "meta", attrs: { property: "og:title", content: ogTitle } });
  if (ogDescription) tags.push({ tag: "meta", attrs: { property: "og:description", content: ogDescription } });
  if (pageUrl) tags.push({ tag: "meta", attrs: { property: "og:url", content: pageUrl } });
  if (siteName) tags.push({ tag: "meta", attrs: { property: "og:site_name", content: siteName } });
  if (shareImage) tags.push({ tag: "meta", attrs: { property: "og:image", content: shareImage } });
  // Twitter card
  tags.push({ tag: "meta", attrs: { name: "twitter:card", content: shareImage ? "summary_large_image" : "summary" } });
  tags.push({ tag: "meta", attrs: { name: "twitter:title", content: twitterTitle } });
  if (twitterDescription) tags.push({ tag: "meta", attrs: { name: "twitter:description", content: twitterDescription } });
  if (twitterImage) tags.push({ tag: "meta", attrs: { name: "twitter:image", content: twitterImage } });
  // Google Search Console
  if (trim(siteSeo.googleVerification)) tags.push({ tag: "meta", attrs: { name: "google-site-verification", content: siteSeo.googleVerification!.trim() } });
  // Structured data
  const ld = structuredDataLd(seo.structuredData, layout, siteKit, pageUrl);
  if (ld) tags.push({ tag: "script", type: "application/ld+json", content: JSON.stringify(ld) });
  return tags;
}

/** Render the head tags as HTML text (for SSR frameworks that want raw HTML). */
export function renderHeadHtml(tags: HeadTag[]): string {
  return tags
    .map((tag) => {
      if (tag.tag === "title") return `<title>${escapeHtml(tag.content)}</title>`;
      if (tag.tag === "meta") return `<meta ${Object.entries(tag.attrs).map(([key, value]) => `${key}="${escapeHtml(value)}"`).join(" ")} />`;
      if (tag.tag === "link") return `<link ${Object.entries(tag.attrs).map(([key, value]) => `${key}="${escapeHtml(value)}"`).join(" ")} />`;
      // JSON-LD's contents are JSON, so only < and & need escaping inside a <script> tag.
      return `<script type="application/ld+json">${tag.content.replace(/</g, "\\u003c")}</script>`;
    })
    .join("\n");
}

// --- sitemap and robots -----------------------------------------------------------------

export type SitemapEntry = {
  /** The page's path on the site (e.g. /about/). Combined with siteUrl to make the absolute URL. */
  path: string;
  /** Last time the page was published (ISO date). */
  lastmod?: string;
  /** Ignored by many crawlers today but harmless to include. */
  changefreq?: "always" | "hourly" | "daily" | "weekly" | "monthly" | "yearly" | "never";
  priority?: number;
};

/** The sitemap.xml file body for the pages the site has. */
export function sitemapXml(siteUrl: string, entries: SitemapEntry[]): string {
  const lines = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'];
  for (const entry of entries) {
    const url = absoluteUrl(siteUrl, entry.path || "/");
    lines.push("  <url>");
    lines.push(`    <loc>${escapeXml(url)}</loc>`);
    if (entry.lastmod) lines.push(`    <lastmod>${escapeXml(entry.lastmod)}</lastmod>`);
    if (entry.changefreq) lines.push(`    <changefreq>${entry.changefreq}</changefreq>`);
    if (typeof entry.priority === "number") lines.push(`    <priority>${entry.priority.toFixed(1)}</priority>`);
    lines.push("  </url>");
  }
  lines.push("</urlset>");
  return lines.join("\n") + "\n";
}

/** The robots.txt file body, always with the standard allow and the sitemap line when a URL is known. */
export function robotsTxt(siteUrl: string, extras?: string): string {
  const lines = ["User-agent: *", "Allow: /"];
  const url = trim(siteUrl);
  if (url) lines.push(`Sitemap: ${absoluteUrl(url, "/sitemap.xml")}`);
  const extra = trim(extras);
  if (extra) {
    lines.push("");
    lines.push(extra);
  }
  return lines.join("\n") + "\n";
}

files.stats.ts:
/**
 * Visitor stats were removed in kit 2.9.0. The `stats` option on
 * `createArmatureKit` and the two helpers exported here (`installStatsBeacon`,
 * `sendBeacon`) are kept as no-ops so a site whose developer wired the old
 * beacon in (for example Tree Test Prep's test copy) keeps building without
 * a single code change. Nothing is sent, nothing is stored, no network call
 * is made.
 *
 * A later kit release may reintroduce visitor stats. If it does, updating the
 * kit will restore the beacon on any site that still has this config wired,
 * without a site-side setup step.
 */

export type StatsConfig = { endpoint: string; siteId: string };

export type BeaconPayload = {
  siteId: string;
  path: string;
  referrerHost: string | null;
  device: "mobile" | "tablet" | "desktop" | "unknown";
  screenBucket: "xs" | "sm" | "md" | "lg" | "xl";
  userAgent: string;
};

/** No-op. Retained so existing calls keep type-checking; always returns true. */
export function shouldSkipBeacon(_win: Window): boolean {
  return true;
}

/** No-op. Retained so existing calls keep type-checking; always returns null. */
export function buildBeaconPayload(_win: Window, _siteId: string): BeaconPayload | null {
  return null;
}

/** No-op. Retained so existing calls keep type-checking. */
