files.store.ts:
/**
 * The kit's store: the site's content, layouts and kit as built, with the draft the
 * editor pushes on top in edit mode. Read with useSyncExternalStore; every change
 * produces a new snapshot object. No React, no DOM: unit-testable.
 */
import { defaultSiteKit } from "./defaults.ts";
import type { LayoutDoc, PostDoc, PostIndex, SiteKit, SiteSectionInfo } from "./types.ts";
import { checkLayout, checkPost, checkPostIndex, checkSiteKit } from "./validate.ts";

export type LinkValue = { label: string; href: string };
export type ListValue = Record<string, string>[];
export type ContentValue = string | LinkValue | ListValue;
export type ContentTree = Record<string, Record<string, Record<string, ContentValue>>>;

export type KitSnapshot = {
  content: ContentTree;
  layouts: Record<string, LayoutDoc>;
  kit: SiteKit;
  editMode: boolean;
  /** The element being typed into on the page: the renderer leaves its DOM alone meanwhile. */
  editing: string | null;
  /** Bumped when an edit on the page ends, so the renderer remounts that element from the saved value. */
  editEpoch: Record<string, number>;
  /** Every blog post the site ships. */
  posts: Record<string, PostDoc>;
  /** The generated posts index (regenerated on every post publish). */
  postIndex: PostIndex;
};

export type SiteSectionRegistration = SiteSectionInfo & { component: unknown };

const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

const PATH_PATTERN = /^([a-z0-9][a-z0-9-]*)\.([a-z0-9][a-z0-9_]*)\.([a-z0-9][a-z0-9_]*)(?:\[(\d+)\]\.([a-z0-9][a-z0-9_]*))?$/;
export type ParsedPath = { slug: string; section: string; field: string; index?: number; itemKey?: string };
export function parseFieldPath(path: string): ParsedPath | null {
  const match = PATH_PATTERN.exec(path);
  if (!match) return null;
  const [, slug = "", section = "", field = "", index, itemKey] = match;
  if (index !== undefined && itemKey !== undefined) return { slug, section, field, index: Number(index), itemKey };
  return { slug, section, field };
}

/**
 * Unwrap `import.meta.glob(..., { eager: true })` modules (or plain objects) into layouts by
 * slug. Every layout goes through the validator (kit/validate.ts): a setting it cannot
 * read is ignored, an element it cannot read is skipped, and the page still renders.
 * Problems are reported once to the console so a developer sees them; the dashboard
 * shows the same list with a "Show me" link.
 */
export function collectLayouts(input: Record<string, unknown> | LayoutDoc[] | undefined): Record<string, LayoutDoc> {
  const out: Record<string, LayoutDoc> = {};
  const values = Array.isArray(input) ? input : Object.values(input ?? {});
  for (const raw of values) {
    const candidate = raw && typeof raw === "object" && "default" in (raw as object) ? (raw as { default: unknown }).default : raw;
    const cleaned = cleanLayout(candidate);
    if (cleaned) out[cleaned.pageSlug] = cleaned;
  }
  return out;
}

/** A layout as the site should render it, or null when it is not a layout at all. */
export function cleanLayout(value: unknown): LayoutDoc | null {
  if (!isLayoutLike(value)) return null;
  const report = checkLayout(value);
  if (report.problems.length > 0 && typeof console !== "undefined") {
    warnLayoutOnce(value.pageSlug, report.problems.length);
  }
  return report.value;
}

const warnedLayouts = new Set<string>();
function warnLayoutOnce(slug: string, count: number): void {
  const key = `${slug}:${count}`;
  if (warnedLayouts.has(key)) return;
  warnedLayouts.add(key);
  console.warn(`Armature: content/layouts/${slug}.json has ${count} ${count === 1 ? "setting" : "settings"} the kit cannot read; ${count === 1 ? "it is" : "they are"} ignored. The dashboard's Pages screen lists ${count === 1 ? "it" : "them"}.`);
}

/** The light guard before validation: the shape of a layout file at all. */
export function isLayoutLike(value: unknown): value is LayoutDoc {
  if (!value || typeof value !== "object") return false;
  const layout = value as Partial<LayoutDoc>;
  return layout.version === 1 && typeof layout.pageSlug === "string" && typeof layout.path === "string" && Array.isArray(layout.root);
}

/** Unwrap post modules from `import.meta.glob(..., { eager: true })` or a plain array. */
export function collectPosts(input: Record<string, unknown> | PostDoc[] | undefined): Record<string, PostDoc> {
  const out: Record<string, PostDoc> = {};
  const values = Array.isArray(input) ? input : Object.values(input ?? {});
  for (const raw of values) {
    const candidate = raw && typeof raw === "object" && "default" in (raw as object) ? (raw as { default: unknown }).default : raw;
    const report = checkPost(candidate);
    if (report.value) out[report.value.slug] = report.value;
  }
  return out;
}

export function createKitStore(config: { content?: ContentTree; layouts?: Record<string, unknown> | LayoutDoc[]; siteKit?: SiteKit | null; posts?: Record<string, unknown> | PostDoc[]; postIndex?: PostIndex | unknown }) {
  const baseContent: ContentTree = clone(config.content ?? {});
  const baseLayouts = collectLayouts(config.layouts);
  const basePosts = collectPosts(config.posts);
  const basePostIndex: PostIndex = config.postIndex ? (checkPostIndex(clone(config.postIndex)).value ?? { version: 1, posts: [] }) : { version: 1, posts: [] };
  // The kit always loads: anything unreadable in site-kit.json falls back to the default kit's value.
  const baseKit: SiteKit = config.siteKit ? (checkSiteKit(clone(config.siteKit)).value ?? defaultSiteKit()) : defaultSiteKit();

  const fieldDraft = new Map<string, unknown>();
  let draftLayouts: Record<string, LayoutDoc | null> | null = null;
  let draftKit: SiteKit | null = null;
  let editMode = false;
  let editing: string | null = null;
  let editEpoch: Record<string, number> = {};

  const sections = new Map<string, SiteSectionRegistration>();
  const listeners = new Set<() => void>();
  let snapshot: KitSnapshot = { content: baseContent, layouts: baseLayouts, kit: baseKit, editMode, editing, editEpoch, posts: basePosts, postIndex: basePostIndex };

  const rebuild = () => {
    let content = baseContent;
    if (fieldDraft.size > 0) {
      content = clone(baseContent);
      for (const [root, value] of fieldDraft) {
        const parsed = parseFieldPath(root);
        if (!parsed) continue;
        const page = (content[parsed.slug] ??= {});
        const section = (page[parsed.section] ??= {});
        section[parsed.field] = value as ContentValue;
      }
    }
    let layouts = baseLayouts;
    if (draftLayouts) {
      layouts = { ...baseLayouts };
      for (const [slug, layout] of Object.entries(draftLayouts)) {
        if (layout === null) delete layouts[slug];
        else layouts[slug] = layout;
      }
    }
    snapshot = { content, layouts, kit: draftKit ?? baseKit, editMode, editing, editEpoch, posts: basePosts, postIndex: basePostIndex };
    for (const listener of listeners) listener();
  };

  return {
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    getSnapshot: () => snapshot,
    /** Replace the whole set of field overrides (the editor sends every field it holds). */
    applyFields(fields: Record<string, unknown>, holdBack?: (root: string) => boolean) {
      const held = new Map<string, unknown>();
      const incoming = new Set(Object.keys(fields));
      for (const root of Array.from(fieldDraft.keys())) if (!incoming.has(root)) fieldDraft.delete(root);
      for (const [root, value] of Object.entries(fields)) {
        if (!parseFieldPath(root)) continue;
        if (holdBack?.(root)) held.set(root, value);
        else fieldDraft.set(root, value);
      }
      rebuild();
      return held;
    },
    setField(root: string, value: unknown) {
      fieldDraft.set(root, value);
      rebuild();
    },
    /** Replace the draft layouts and kit. A null layout means "deleted in the draft". */
    applyLayouts(layouts: Record<string, LayoutDoc | null> | null, kit: SiteKit | null) {
      if (layouts) {
        const cleaned: Record<string, LayoutDoc | null> = {};
        for (const [slug, layout] of Object.entries(layouts)) cleaned[slug] = layout === null ? null : (checkLayout(layout).value ?? null);
        draftLayouts = cleaned;
      } else draftLayouts = null;
      draftKit = kit ? checkSiteKit(kit).value : null;
      rebuild();
    },
    setEditMode(next: boolean) {
      if (editMode === next) return;
      editMode = next;
      rebuild();
    },
    /**
     * Set one prop of one element in the draft (the value typed on the page), so the
     * element remounts showing it before the editor's next full draft arrives.
     */
    patchElementProp(id: string, key: string, value: unknown) {
      const patch = (elements: LayoutDoc["root"]): LayoutDoc["root"] => {
        let changed = false;
        const next = elements.map((element) => {
          if (element.id === id) {
            changed = true;
            return { ...element, props: { ...element.props, [key]: value } };
          }
          if (!element.children) return element;
          const children = patch(element.children);
          if (children === element.children) return element;
          changed = true;
          return { ...element, children };
        });
        return changed ? next : elements;
      };
      for (const [slug, layout] of Object.entries(snapshot.layouts)) {
        const root = patch(layout.root);
        if (root !== layout.root) {
          draftLayouts = { ...(draftLayouts ?? {}), [slug]: { ...layout, root } };
          rebuild();
          return;
        }
      }
    },
    /** The bridge marks the element being typed into; clearing it remounts that element. */
    setEditing(id: string | null) {
      if (editing === id) return;
      if (editing) editEpoch = { ...editEpoch, [editing]: (editEpoch[editing] ?? 0) + 1 };
      editing = id;
      rebuild();
    },
    registerSection(key: string, registration: Omit<SiteSectionRegistration, "key">) {
      sections.set(key, { key, ...registration });
    },
    getSection: (key: string) => sections.get(key),
    listSections: (): SiteSectionInfo[] => Array.from(sections.values()).map(({ key, label, repeatable }) => ({ key, label, repeatable })),
    baseContent,
    baseLayouts,
    baseKit,
  };
}

export type KitStore = ReturnType<typeof createKitStore>;

files.types.ts:
/**
 * The page builder's data model (site contract v2). Plain TypeScript types with no
 * dependencies, so the kit can be copied into a site as is. The dashboard and the edge
 * functions validate these shapes with the zod schemas in shared/builder/schema.ts,
 * which are typed against this file so the two can never drift.
 *
 * Layout files live at content/layouts/<pageSlug>.json in the site's repository and
 * the site kit at content/site-kit.json.
 */

// --- responsive values -------------------------------------------------------------------

export type Device = "desktop" | "tablet" | "mobile";

/** A value with per-device overrides. Tablet inherits desktop, mobile inherits tablet. */
export type Responsive<T> = { desktop: T; tablet?: T; mobile?: T };
export type MaybeResponsive<T> = T | Responsive<T>;

// --- sizes, colours, references ----------------------------------------------------------

export type Unit = "px" | "%" | "em" | "rem" | "vw" | "vh" | "vmin" | "vmax" | "ch" | "ex" | "svh" | "dvh" | "lvh" | "svw" | "dvw" | "lvw" | "pt" | "auto" | "";
/**
 * Every size control stores a value and a unit. With "auto" the value is ignored; "" is
 * unitless (line-height 1.4, or a bare 0). Decimals and negative values are fine wherever
 * CSS allows them (letter-spacing -0.02em, margin -20px).
 */
export type Size = { value: number; unit: Unit };
export type Sides<T> = { top?: T; right?: T; bottom?: T; left?: T };
export type Corners<T> = { topLeft?: T; topRight?: T; bottomRight?: T; bottomLeft?: T };

/**
 * A colour is a literal ("#1f3a2e", "#1f3a2e80", "rgba(...)", "transparent") or a kit
 * reference such as "kit:color.primary" or "kit:color.custom.<id>".
 */
export type Color = string;
/** A font family literal or "kit:font.heading" / "kit:font.body" / "kit:font.custom.<id>". */
export type FontRef = string;

export type Gap = { column?: Size; row?: Size };

// --- style (the Style tab) -----------------------------------------------------------------

/** Any whole number from 1 to 1000 (variable fonts use 650, 450…), or a CSS keyword. */
export type FontWeight = number | "normal" | "bold" | "lighter" | "bolder";
export type TextTransform = "none" | "uppercase" | "lowercase" | "capitalize";
export type FontStyle = "normal" | "italic" | "oblique";
export type TextDecoration = "none" | "underline" | "line-through" | "overline";
export type TextAlign = "left" | "center" | "right" | "justify" | "start" | "end";

export type Typography = {
  /** A kit typography preset, e.g. "kit:type.h2". Explicit values below override it. */
  preset?: string;
  fontFamily?: FontRef;
  fontSize?: MaybeResponsive<Size>;
  fontWeight?: MaybeResponsive<FontWeight>;
  textTransform?: MaybeResponsive<TextTransform>;
  fontStyle?: MaybeResponsive<FontStyle>;
  textDecoration?: MaybeResponsive<TextDecoration>;
  lineHeight?: MaybeResponsive<Size>;
  letterSpacing?: MaybeResponsive<Size>;
  wordSpacing?: MaybeResponsive<Size>;
  textAlign?: MaybeResponsive<TextAlign>;
};

export type Shadow = { x: number; y: number; blur: number; spread?: number; color: Color; inset?: boolean };

export type BorderStyle = "none" | "solid" | "dashed" | "dotted" | "double" | "groove" | "ridge" | "inset" | "outset" | "hidden";
export type Border = {
  style?: MaybeResponsive<BorderStyle>;
  width?: MaybeResponsive<Sides<Size>>;
  color?: MaybeResponsive<Color>;
  radius?: MaybeResponsive<Corners<Size>>;
};

export type GradientStop = { color: Color; position: number };
export type Background =
  | { kind: "none" }
  | { kind: "color"; color: Color }
  | { kind: "gradient"; type: "linear" | "radial"; angle?: number; stops: GradientStop[] }
  | {
      kind: "image";
      src: string;
      position?: string;
      attachment?: "scroll" | "fixed";
      repeat?: "no-repeat" | "repeat" | "repeat-x" | "repeat-y";
      /** A keyword, or any CSS background-size such as "100% auto" or "480px". */
      size?: "auto" | "cover" | "contain" | (string & {});
      /** Focal point as percentages, used when size is cover. */
      focal?: { x: number; y: number };
    }
  | { kind: "video"; src: string; poster?: string; loop?: boolean; playOnMobile?: boolean };

export type BackgroundOverlay = { background: Background; opacity: number; blend?: string };

export const BLEND_MODES = ["normal", "multiply", "screen", "overlay", "darken", "lighten", "color-dodge", "color-burn", "hard-light", "soft-light", "difference", "exclusion", "hue", "saturation", "color", "luminosity"] as const;
export type BlendMode = (typeof BLEND_MODES)[number];

/** An outline drawn around the glyphs (-webkit-text-stroke). */
export type TextStroke = { width: number; color: Color };

export type StyleBase = {
  typography?: Typography;
  color?: MaybeResponsive<Color>;
  textShadow?: MaybeResponsive<Shadow>;
  textStroke?: MaybeResponsive<TextStroke>;
  boxShadow?: MaybeResponsive<Shadow>;
  border?: Border;
  background?: MaybeResponsive<Background>;
  backgroundOverlay?: MaybeResponsive<BackgroundOverlay>;
  opacity?: MaybeResponsive<number>;
  /** How the element blends with what is behind it (mix-blend-mode). */
  mixBlendMode?: MaybeResponsive<BlendMode>;
  /** Transition duration in milliseconds for hover changes. */
  transition?: number;
};

export type Style = StyleBase & { hover?: StyleBase };

// --- advanced (the Advanced tab) -----------------------------------------------------------

export type WidthMode = "full" | "inline" | "custom";
export type AlignSelf = "auto" | "flex-start" | "center" | "flex-end" | "stretch";
export type PositionType = "default" | "absolute" | "fixed" | "relative" | "sticky";
export type AnimationType =
  | "none"
  | "fadeIn"
  | "fadeInUp"
  | "fadeInDown"
  | "fadeInLeft"
  | "fadeInRight"
  | "zoomIn"
  | "slideInUp"
  | "bounceIn";

export type Advanced = {
  margin?: MaybeResponsive<Sides<Size>>;
  padding?: MaybeResponsive<Sides<Size>>;
  width?: MaybeResponsive<WidthMode>;
  customWidth?: MaybeResponsive<Size>;
  maxWidth?: MaybeResponsive<Size>;
  alignSelf?: MaybeResponsive<AlignSelf>;
  order?: MaybeResponsive<number>;
  flexGrow?: MaybeResponsive<number>;
  flexShrink?: MaybeResponsive<number>;
  /** Inside a grid: how many columns and rows the element spans. */
  gridColumnSpan?: MaybeResponsive<number>;
  gridRowSpan?: MaybeResponsive<number>;
  position?: {
    type: PositionType;
    top?: MaybeResponsive<Size>;
    right?: MaybeResponsive<Size>;
    bottom?: MaybeResponsive<Size>;
    left?: MaybeResponsive<Size>;
    zIndex?: number;
  };
  animation?: { type: AnimationType; duration?: number; delay?: number };
  /** A small effect while the pointer is over the element. */
  hoverAnimation?: HoverAnimation;
  /** Scrolling effects: vertical parallax (-10 to 10; 0 is none). */
  scroll?: { parallax?: number };
  /** Hidden per device. A hidden element still shows in the editor at 40% with a badge. */
  hidden?: { desktop?: boolean; tablet?: boolean; mobile?: boolean };
  /** Agency only from here on. */
  cssId?: string;
  cssClasses?: string;
  attributes?: { name: string; value: string }[];
  /** Scoped to this element's selector; "selector" in the text stands for it. */
  customCss?: string;
};

// --- rich text (TipTap-compatible JSON, rendered by the kit's own whitelist renderer) ------

export type RichMark =
  | { type: "bold" }
  | { type: "italic" }
  | { type: "underline" }
  | { type: "strike" }
  | { type: "code" }
  | { type: "link"; attrs: { href: string; target?: "_blank" | null } }
  | { type: "textStyle"; attrs: { color?: string } }
  | { type: "highlight"; attrs: { color?: string } };

export type RichText = { type: "text"; text: string; marks?: RichMark[] };
export type RichInline = RichText | { type: "hardBreak" };
export type RichBlock =
  | { type: "paragraph"; attrs?: { textAlign?: TextAlign }; content?: RichInline[] }
  | { type: "heading"; attrs: { level: 1 | 2 | 3 | 4 | 5 | 6; textAlign?: TextAlign }; content?: RichInline[] }
  | { type: "bulletList"; content: RichListItem[] }
  | { type: "orderedList"; attrs?: { start?: number }; content: RichListItem[] }
  | { type: "blockquote"; content: RichBlock[] };
export type RichListItem = { type: "listItem"; content: RichBlock[] };
export type RichDoc = { type: "doc"; content: RichBlock[] };

// --- icons ---------------------------------------------------------------------------------

/** An icon's SVG nodes (a subset of the lucide format), saved so the site needs no icon library. */
export type IconValue = { name: string; nodes: [string, Record<string, string>][] };

// --- links -------------------------------------------------------------------------------

export type LinkValue = { href: string; newTab?: boolean; rel?: string };

// --- elements ------------------------------------------------------------------------------

export type ElementMeta = { createdBy: string; updatedAt: string };

/**
 * What the validator puts in place of an element it could not read (kit/validate.ts).
 * The site skips it, the editor shows "Unsupported element", and a publish writes the
 * original element back exactly as it was.
 */
export const UNSUPPORTED_TYPE = "unsupported";
export type UnsupportedProps = { originalType: string; reason: string };

export type Element = {
  /** Eight characters, [a-z0-9]. Stable for the element's life; its CSS class is .ae-<id>. */
  id: string;
  type: string;
  label?: string;
  props: Record<string, unknown>;
  style: Style;
  advanced: Advanced;
  children?: Element[];
  locked?: boolean;
  meta: ElementMeta;
};

/** Structured data (schema.org) a page can add. Every kind is one plain-fields form the person fills in. */
export type StructuredDataKind = "LocalBusiness" | "Organization" | "Article" | "FAQ" | "BreadcrumbList";
export type ArticleData = {
  headline?: string;
  description?: string;
  image?: string;
  author?: string;
  datePublished?: string;
  dateModified?: string;
};
export type BreadcrumbItem = { name: string; url: string };
/**
 * Structured data on a page. LocalBusiness/Organization use the site-wide business
 * details (siteKit.seo.business) with these overrides; FAQ reads an accordion widget's
 * items on the page; BreadcrumbList takes the list on the page.
 */
export type PageStructuredData =
  | { kind: "none" }
  | { kind: "LocalBusiness"; override?: Partial<LocalBusinessData> }
  | { kind: "Organization"; override?: Partial<LocalBusinessData> }
  | { kind: "Article"; article: ArticleData }
  | { kind: "FAQ"; fromAccordionId?: string }
  | { kind: "BreadcrumbList"; items: BreadcrumbItem[] };

export type PageSeo = {
  /** Search-result title, up to about 60 characters. */
  title?: string;
  /** Search-result description, up to about 160 characters. */
  description?: string;
  /** An https:// address or a picture on this site (/assets/...), shown as the sharing image. */
  ogImage?: string;
  /** Overrides for the social share title on Open Graph (Facebook, LinkedIn, iMessage). */
  ogTitle?: string;
  ogDescription?: string;
  /** Overrides for the X/Twitter share card. */
  twitterTitle?: string;
  twitterDescription?: string;
  twitterImage?: string;
  /** The absolute URL that is the canonical version of this page. Empty uses the site URL + the page's path. */
  canonical?: string;
  /** Hide from search engines (adds noindex). */
  noindex?: boolean;
  /** Ask search engines not to follow links on this page (adds nofollow). */
  nofollow?: boolean;
  /** Structured data (schema.org) to add to the page. */
  structuredData?: PageStructuredData;
};
export type PageSettings = { hideTitle?: boolean; bodyBackground?: Color | null; fullCanvas?: boolean };

export type LayoutDoc = {
  version: 1;
  pageSlug: string;
  path: string;
  /** Required for builder-only pages (coded pages carry their label in schema.json). */
  label?: string;
  seo?: PageSeo;
  pageSettings?: PageSettings;
  root: Element[];
};

// --- posts (the blog) ------------------------------------------------------------------

/**
 * A blog post lives at content/posts/<slug>.json. It is a layout file with
 * `kind: "post"` and post fields in `settings`. The body is the layout tree so
 * every widget, style and revision the builder ships works unchanged.
 */
export type PostSettings = {
  title: string;
  excerpt?: string;
  /** A path on this site (/assets/…) or an https:// URL. */
  coverImage?: string;
  /** Auth user id who wrote the post. */
  author?: string;
  /** Copied from the profile on publish, so the site never has to look it up. */
  authorName?: string;
  /** ISO date-time. An empty string, undefined or a date in the future = draft/scheduled. */
  publishedAt?: string;
  categories?: string[];
  tags?: string[];
  seo?: PageSeo;
};

export type PostDoc = {
  version: 1;
  kind: "post";
  slug: string;
  path: string;
  settings: PostSettings;
  root: Element[];
};

/** Every post's summary, regenerated by the publish function on every post commit. */
export type PostIndexEntry = {
  slug: string;
  path: string;
  title: string;
  excerpt: string;
  coverImage: string | null;
  authorName: string;
  publishedAt: string;
  categories: string[];
  tags: string[];
};

export type PostIndex = {
  version: 1;
  posts: PostIndexEntry[];
};

/** Categories and tags with their slugs, names and descriptions (content/taxonomies.json). */
export type TaxonomyTerm = { slug: string; name: string; description?: string };
export type Taxonomies = { categories: TaxonomyTerm[]; tags: TaxonomyTerm[] };

// --- widget props (the Content tab) -----------------------------------------------------------

export type ContainerTag = "div" | "section" | "header" | "footer" | "article" | "aside" | "nav" | "main";
export type FlexDirection = "row" | "column" | "row-reverse" | "column-reverse";
export type Justify = "flex-start" | "center" | "flex-end" | "space-between" | "space-around" | "space-evenly" | "start" | "end";
export type AlignItems = "flex-start" | "center" | "flex-end" | "stretch" | "baseline" | "start" | "end";

export type ContainerProps = {
  tag?: ContainerTag;
  /** Boxed keeps the content at the kit's content width; full lets it span the page. */
  layout?: "boxed" | "full";
  contentWidth?: MaybeResponsive<Size>;
  /** "screen" fits the viewport height. */
  minHeight?: MaybeResponsive<Size | "screen">;
  direction?: MaybeResponsive<FlexDirection>;
  justify?: MaybeResponsive<Justify>;
  align?: MaybeResponsive<AlignItems>;
  gap?: MaybeResponsive<Gap>;
  wrap?: MaybeResponsive<boolean>;
  overflow?: "visible" | "hidden";
  link?: LinkValue;
};

export type GridProps = {
  tag?: ContainerTag;
  layout?: "boxed" | "full";
  contentWidth?: MaybeResponsive<Size>;
  minHeight?: MaybeResponsive<Size | "screen">;
  /** A count, or a custom grid-template-columns string. */
  columns?: MaybeResponsive<number | string>;
  rows?: MaybeResponsive<number | string>;
  gap?: MaybeResponsive<Gap>;
  autoFlow?: "row" | "column" | "row dense" | "column dense";
  justifyItems?: MaybeResponsive<"start" | "center" | "end" | "stretch">;
